// ---------- helpers ----------
const card = (r, why) => ({ source: 'omt', id: r.id, title: r.title, author: r.author, accessType: r.accessType, url: `resource.html?id=${encodeURIComponent(r.id)}`, why });

function whyMatch(r, parsed) {
  const hay = `${r.title} ${(r.tags ?? []).join(' ')} ${r.description} ${CATEGORIES[r.category]?.label ?? ''}`.toLowerCase();
  const hit = parsed.terms.filter((t) => hay.includes(t));
  const bits = [];
  if (hit.length) bits.push(`Matches “${hit.slice(0, 3).join('”, “')}”`);
  if (r.level) bits.push(`${LEVELS[r.level]} level`);
  bits.push(ACCESS[r.accessType]?.label ?? '');
  return bits.filter(Boolean).join(' · ');
}

const GREETING = /^(hi|hello|hey|hiya|good (morning|afternoon|evening)|help|what can you do)[\s!.?]*(there|omt|omt ai)?[\s!.?]*$/i;
const ASK_EXPLAIN = /\b(explain|about|overview|summar|main ideas?|what (is|does) (this|it)|tell me|who is it for|themes?)\b/i;
const ASK_ALTERNATIVE = /\b(alternative|similar|free (version|copy|option)|instead|other (books|resources))\b/i;

function explainResource(r, all) {
  const kind = KINDS[r.kind]?.toLowerCase() ?? 'resource';
  const access = ACCESS[r.accessType] ?? ACCESS.info;
  const audience = r.level === 'beginner' ? 'beginners and students who are new to the topic'
    : r.level === 'intermediate' ? 'learners who already know the basics' : 'readers ready for an advanced, in-depth text';
  const topics = (r.tags ?? []).filter((t) => !['book', 'textbook', 'openstax', 'template', 'official', 'microsoft', 'free', 'classic', 'public domain'].includes(t)).slice(0, 5);
  const limitation = r.accessType === 'omt'
    ? 'This summary is based on the resource details. You can read the full guide on its resource page.'
    : 'This overview is based on our catalogue information. I have not read the full text, so check the source for details.';
  const lines = [
    `**${r.title}**${r.author ? ` by ${r.author}` : ''} is a ${kind}${r.year && /^\d/.test(r.year) ? ` (${r.year})` : ''} in **${CATEGORIES[r.category]?.label ?? 'our library'}**.`,
    '',
    `- **What it covers:** ${r.description}`,
    topics.length ? `- **Key topics:** ${topics.join(', ')}` : '',
    r.level ? `- **Who it's for:** ${audience}` : '',
    `- **How to access it:** ${access.title}.${r.license ? ` Licence: ${r.license}.` : ''}`,
    '',
    `*${limitation}*`,
  ];
  if (r.accessType === 'paid') lines.push('', 'Because this book is in copyright, borrowing it from a library or Open Library is a free, legal option.');
  return { reply: lines.filter((l, i, a) => l !== '' || a[i - 1] !== '').join('\n'), resources: [card(r, 'The resource you asked about')] };
}

function alternatives(r, all) {
  const free = relatedResources(all, r, 10).filter((x) => x.accessType !== 'paid').slice(0, 4);
  if (!free.length) return { reply: `I couldn't find free alternatives to **${r.title}** in our library yet. Try searching Open Library from the library page.`, resources: [] };
  return {
    reply: `Here are free resources on topics similar to **${r.title}**:`,
    resources: free.map((x) => card(x, `${CATEGORIES[x.category]?.label ?? ''} · ${ACCESS[x.accessType]?.label}`)),
  };
}

async function findResources(message, all) {
  const parsed = parseQuery(message);
  const results = searchCatalog(all, { q: message }).slice(0, 4);
  let external = [];
  const wantsBooks = parsed.hints.kind === 'book' || results.length < 2;
  if (wantsBooks && parsed.terms.length) {
    const q = parsed.terms.join(' ');
    try {
      external = (await searchExternalBooks(q)).slice(0, 4).map((d) => ({ source: d.source, title: d.title, author: d.authors, year: d.year, accessType: d.access, url: d.url }));
    } catch {
      try { external = (await searchOpenLibrary(q, { limit: 3 })); } catch { external = []; }
    }
  }
  const resources = [
    ...results.map((r) => card(r, whyMatch(r, parsed))),
    ...external.map((d) => (d.accessType ? d : { source: 'openlibrary', title: d.title, author: d.author, year: d.year, access: d.access, url: d.url })),
  ];
  if (!resources.length) {
    return {
      reply: `I couldn't find anything for that in our library or on Open Library. Try:\n\n- naming the subject plus your level, e.g. "beginner Excel" or "intro to economics"\n- searching for the author's name\n- browsing [the full library](library.html)`,
      resources: [],
    };
  }
  const intro = results.length
    ? `Here ${results.length === 1 ? 'is a resource' : `are ${results.length} resources`} from the OMT library that match what you asked for${external.length ? ', plus books from outside the library' : ''}:`
    : 'I didn\'t find a match in the OMT library, but I found these books elsewhere:';
  const note = external.length ? '\n\nOutside books come from Google Books, Open Library and Project Gutenberg. Each label shows whether you can read it in full, preview it, borrow it or buy it.' : '';
  return { reply: intro + note, resources };
}

/** Produce a demo reply for the latest user message. */
export async function demoReply({ message, resource, all }) {
  const text = message.trim();
  if (GREETING.test(text)) {
    return {
      reply: `I can help you:\n\n1. **Find a book or resource**: e.g. "a free book to learn Linux"\n2. **Explain a resource**: open any resource and choose "Ask AI about this resource"\n3. **Explain a concept**: e.g. "Explain subnetting", "4G vs 5G core", "Docker vs Kubernetes"\n\nWhat are you working on?`,
      resources: [],
    };
  }
  if (resource && ASK_ALTERNATIVE.test(text)) return alternatives(resource, all);
  if (resource && (ASK_EXPLAIN.test(text) || text.length < 25)) return explainResource(resource, all);

  const lower = text.toLowerCase();
  const concept = CONCEPTS.find((c) => c.keys.test(lower));
  if (concept) {
    const related = searchCatalog(all, { q: concept.query }).slice(0, 3);
    return { reply: concept.text, resources: related.map((r) => card(r, 'Learn more')) };
  }
  return findResources(text, all);
}
